-- Deeply nested and long-join analytical queries as produced by BI tools
SELECT a.id, a.name, b.total, c.cnt FROM accounts a INNER JOIN (SELECT account_id, SUM(amount) AS total FROM ledger WHERE posted_at BETWEEN '2025-01-01' AND '2025-12-31' GROUP BY account_id HAVING SUM(amount) <> 0) b ON b.account_id = a.id LEFT JOIN (SELECT account_id, COUNT(*) AS cnt FROM tickets WHERE status IN ('open', 'pending') GROUP BY account_id) c ON c.account_id = a.id WHERE a.active = 1 AND a.id NOT IN (SELECT account_id FROM blocked) ORDER BY b.total DESC, a.name ASC LIMIT 50;
SELECT * FROM (SELECT * FROM (SELECT * FROM (SELECT id, v FROM t WHERE v > 0) l3 WHERE id > 1) l2 WHERE id < 100) l1 ORDER BY id;
SELECT x.id FROM t1 x WHERE x.id IN (SELECT y.id FROM t2 y WHERE y.v > (SELECT AVG(z.v) FROM t3 z WHERE z.k IN (SELECT w.k FROM t4 w WHERE EXISTS (SELECT 1 FROM t5 q WHERE q.w = w.id))));
SELECT p.id, p.name, c.name AS category, b.name AS brand, s.name AS supplier, w.name AS warehouse, i.qty, pr.price, cur.code FROM products p JOIN categories c ON c.id = p.category_id JOIN brands b ON b.id = p.brand_id JOIN suppliers s ON s.id = p.supplier_id JOIN inventory i ON i.product_id = p.id JOIN warehouses w ON w.id = i.warehouse_id JOIN prices pr ON pr.product_id = p.id AND pr.valid_to IS NULL JOIN currencies cur ON cur.id = pr.currency_id WHERE i.qty > 0 AND p.active;
SELECT CASE WHEN a > 0 THEN CASE WHEN b > 0 THEN 'pp' ELSE 'pn' END ELSE CASE WHEN b > 0 THEN 'np' ELSE 'nn' END END AS quad, COUNT(*) FROM pts GROUP BY quad;
SELECT ((((a + b) * c) - d) / NULLIF(e, 0)) AS r, -a AS neg, +b AS pos, NOT (a > b AND (c < d OR e = f)) AS flag FROM nums;
SELECT * FROM t WHERE a = 1 AND (b = 2 OR c = 3) AND NOT (d = 4 OR e = 5) AND f IN (1, 2, 3) AND g BETWEEN 1 AND 10 AND h LIKE 'x%' AND i IS NULL;
SELECT COALESCE((SELECT MAX(v) FROM t2 WHERE t2.id = t1.id), (SELECT MIN(v) FROM t3 WHERE t3.id = t1.id), 0) FROM t1;
SELECT u.id, (SELECT GROUP_CONCAT(r.name SEPARATOR ',') FROM roles r JOIN user_roles ur ON ur.role_id = r.id WHERE ur.user_id = u.id) AS roles FROM users u;
SELECT t.id, t.n FROM (SELECT id, COUNT(*) AS n FROM events GROUP BY id) AS t JOIN (SELECT id FROM users WHERE active = 1) AS u USING (id) WHERE t.n > 5;
SELECT a.x, b.y FROM a JOIN b ON a.id = b.id AND (a.k = b.k OR (a.k IS NULL AND b.k IS NULL));
SELECT * FROM a LEFT JOIN b ON a.id = b.a_id LEFT JOIN c ON b.id = c.b_id RIGHT JOIN d ON d.id = c.d_id;
SELECT * FROM a JOIN (b JOIN c ON b.id = c.b_id) ON a.id = b.a_id;
SELECT * FROM a, b, c WHERE a.id = b.id AND b.id = c.id;
SELECT DISTINCT a.x FROM a WHERE a.y > 1 ORDER BY a.x LIMIT 5;
SELECT COUNT(DISTINCT a, b) FROM t;
SELECT SUM(IF(status = 'paid', total, 0)) AS paid, SUM(IF(status = 'new', total, 0)) AS pending FROM orders;
SELECT user_id, MAX(CASE WHEN k = 'a' THEN v END) AS a, MAX(CASE WHEN k = 'b' THEN v END) AS b FROM kv GROUP BY user_id;
SELECT a, b, COUNT(*) FROM t GROUP BY a, b WITH ROLLUP HAVING COUNT(*) > 1 ORDER BY a DESC, b;
SELECT * FROM t1 WHERE id = ANY (SELECT id FROM t2) ORDER BY RAND() LIMIT 1;
SELECT ROUND(AVG(total), 2), FLOOR(MAX(total)), CEIL(MIN(total)), ABS(SUM(total)), POWER(2, 10), SQRT(16), MOD(10, 3) FROM orders;
VALUES (1, 'a'), (2, 'b');
SELECT * FROM t1 WHERE a IN (SELECT a FROM t2 UNION SELECT a FROM t3);
SELECT * FROM (SELECT a FROM t1 UNION ALL SELECT a FROM t2) u ORDER BY a;
SELECT (SELECT 1) + (SELECT 2);
SELECT EXISTS (SELECT 1 FROM t WHERE a = 1);
SELECT id, name FROM users WHERE MATCH (name, bio) AGAINST ('database' IN NATURAL LANGUAGE MODE);
SELECT id FROM docs WHERE MATCH (body) AGAINST ('+sql -nosql' IN BOOLEAN MODE);
SELECT ST_AsText(ST_GeomFromText('POINT(1 1)')), ST_Distance(a.pt, b.pt) FROM a, b;
SELECT INTERVAL(5, 1, 3, 7), FIELD('b', 'a', 'b'), ELT(2, 'x', 'y'), FIND_IN_SET('a', 'a,b');
SELECT BIT_AND(a), BIT_OR(a), BIT_XOR(a), VARIANCE(a), STD(a) FROM t;
